  const c = splitRow(line);
  if (!c.every(x => /^:?-+:?$/.test(x))) return null;
  return c.map(x => (x[0] === ':' ? (x.endsWith(':') ? 'center' : 'left') : x.endsWith(':') ? 'right' : null));
