const args = process.argv.slice(2);
const file = args.find(a => a === '-' || !a.startsWith('--'));
if (!file) { console.error('usage: cli.js <file.md|-> [--toc] [--ids]'); process.exit(2); }
const src = readFileSync(file === '-' ? 0 : file, 'utf8');
